<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\TenantLoginProviderSourceOptions;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Accessor\TenantLoginProviderSourceAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderSourceAccessor trait.
 *
 * Covers null default, string/VO assignment via withSource,
 * getSource/source accessors, and isSourceChanged with/without original.
 */
class TenantLoginProviderSourceAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withSource creates a new instance with the Source set
     * from a string value, and getSource returns the primitive string.
     */
    public function testWithSourceFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderSourceAccessorUnitTest();

        // Act
        $result = $holder->withSource(TenantLoginProviderSourceOptions::GOOGLE);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(TenantLoginProviderSourceOptions::GOOGLE, $result->getSource());
    }
    /**
     * Asserts that withsource has access to the value object
     * from a string value, and getSource returns the primitive string.
     */
    public function testWithSourceFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderSourceAccessorUnitTest();

        // Act
        $result = $holder->withSource(TenantLoginProviderSourceOptions::GOOGLE);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(TenantLoginProviderSourceOptions::GOOGLE, $result->source()->value());
    }
    public function testChangedSource(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderSourceAccessorUnitTest()->withSource(TenantLoginProviderSourceOptions::GOOGLE);
        $original = $holder->withSource( TenantLoginProviderSourceOptions::GOOGLE);
        $same = $holder->withSource( TenantLoginProviderSourceOptions::GOOGLE);
        $modified = $holder->withSource(TenantLoginProviderSourceOptions::GITHUB);

        // Act
        $withSame = $original->isSourceChanged( $same );
        $withDiferent = $original->isSourceChanged( $modified );

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantLoginProviderSourceAccessorUnitTest
{
  use TenantLoginProviderSourceAccessor;
}
